'use client';

import Image from 'next/image';
import { cn } from '@/lib/utils';
import { useT } from '@/lib/i18n/client';

/**
 * The church's existing emblem.
 *
 * The original artwork (`public/brand/logo-original.jpg`, a copy of the
 * `11.jfif` that shipped with the project) is never modified. Two derived
 * assets are generated by `npm run logo:generate`:
 *
 *  - `logo-transparent.png` — original colours, white background removed
 *  - `logo-mask.png`        — alpha silhouette used as a CSS mask
 *
 * `variant="themed"` paints the silhouette with the `--logo-color` token, so
 * re-colouring the whole app's logo is a one-line change in `globals.css`.
 * Shape, proportions and the emblem itself are always preserved.
 */
type LogoVariant = 'themed' | 'original' | 'contrast';

export function LogoMark({
  variant = 'themed',
  size = 40,
  className,
}: {
  variant?: LogoVariant;
  size?: number;
  className?: string;
}) {
  const t = useT();

  if (variant === 'original') {
    return (
      <Image
        src="/brand/logo-transparent.png"
        alt={t('brand.church')}
        width={size}
        height={size}
        priority
        className={cn('object-contain', className)}
        style={{ width: size, height: size }}
      />
    );
  }

  const color =
    variant === 'contrast' ? 'var(--logo-color-contrast)' : 'var(--logo-color)';

  return (
    <span
      role="img"
      aria-label={t('brand.church')}
      className={cn('inline-block shrink-0', className)}
      style={{
        width: size,
        height: size,
        backgroundColor: color,
        WebkitMaskImage: 'url(/brand/logo-mask.png)',
        maskImage: 'url(/brand/logo-mask.png)',
        WebkitMaskSize: 'contain',
        maskSize: 'contain',
        WebkitMaskRepeat: 'no-repeat',
        maskRepeat: 'no-repeat',
        WebkitMaskPosition: 'center',
        maskPosition: 'center',
      }}
    />
  );
}

export function Logo({
  variant = 'themed',
  size = 40,
  showText = true,
  subtitle,
  className,
}: {
  variant?: LogoVariant;
  size?: number;
  showText?: boolean;
  /** Pass `null` to hide the sub-line. Defaults to the ministry name. */
  subtitle?: string | null;
  className?: string;
}) {
  const t = useT();
  const onDark = variant === 'contrast';
  const sub = subtitle === undefined ? t('brand.ministry') : subtitle;
  const name = t('brand.name');
  return (
    <span className={cn('inline-flex items-center gap-2.5', className)}>
      <LogoMark variant={variant} size={size} />
      {showText ? (
        <span className="flex flex-col leading-none">
          <span
            className={cn(
              'font-display text-[1.0625rem] font-extrabold tracking-tight',
              onDark ? 'text-white' : 'text-brand-800',
            )}
          >
            {name}
          </span>
          {sub ? (
            <span
              className={cn(
                'mt-1 text-[0.6875rem] font-medium tracking-[0.14em] uppercase',
                onDark ? 'text-brand-100/80' : 'text-muted',
              )}
            >
              {sub}
            </span>
          ) : null}
        </span>
      ) : null}
    </span>
  );
}
